=== FILE: lifo4_fcov.sv ===
// lifo4_fcov: functional coverage model for the lifo4 stack block.
// Built from the approved requirement-to-plan matrix (traceability_matrix.md,
// plan-audit stage). Bins are planned from the matrix scenarios, not from RTL.
//
// CLOSURE STATEMENT
// Sampling: every rising edge of clk, using the port values just before the
// edge. count/empty/full describe the stack as it stood before the edge.
// Crosses and occupancy bins are sampled only with rst_n high, because the
// matrix rules apply with rst_n high. Occupancy class is taken from count:
// empty = count 0, mid = count 1..3 (neither empty nor full), full = count 4.
//
// Planned bins (15):
//  0  PUSH_EMPTY  LIFO-PUSH        push alone, stack empty
//  1  PUSH_MID    LIFO-PUSH        push alone, stack neither empty nor full
//  2  PUSH_FULL   LIFO-OVERFLOW    push alone, stack full
//  3  POP_EMPTY   LIFO-UNDERFLOW   pop alone, stack empty
//  4  POP_MID     LIFO-POP         pop alone, stack neither empty nor full
//  5  POP_FULL    LIFO-POP         pop alone, stack full
//  6  BOTH_EMPTY  LIFO-BOTH-EMPTY  push and pop together, stack empty
//  7  BOTH_MID    LIFO-REPLACE     push and pop together, neither empty nor full
//  8  BOTH_FULL   LIFO-REPLACE     push and pop together, stack full
//  9  OCC0        (all)            occupancy 0
// 10  OCC1        (all)            occupancy 1
// 11  OCC2        (all)            occupancy 2
// 12  OCC3        (all)            occupancy 3
// 13  OCC4        (all)            occupancy 4
// 14  RESET_HELD  LIFO-RESET       reset applied while the stack holds a word
//                                  (rst_n low at the edge with count != 0)
//
// Exclusions: none. The matrix waives no scenario and names none unreachable.
// Excluded bins would be counted in neither 'planned' nor 'holes'.
//
// Illegal values: count > 4 with rst_n high is reported with $error. It is
// not a coverage bin.

module lifo4_fcov (
    input  logic       clk, rst_n, push, pop,
    input  logic [7:0] din, dout,
    input  logic [2:0] count,
    input  logic       empty, full, err,
    output int         planned,   // how many bins the model plans
    output int         holes      // how many of them have not been hit yet
);

    localparam int NBINS = 15;

    localparam int B_PUSH_EMPTY = 0;
    localparam int B_PUSH_MID   = 1;
    localparam int B_PUSH_FULL  = 2;
    localparam int B_POP_EMPTY  = 3;
    localparam int B_POP_MID    = 4;
    localparam int B_POP_FULL   = 5;
    localparam int B_BOTH_EMPTY = 6;
    localparam int B_BOTH_MID   = 7;
    localparam int B_BOTH_FULL  = 8;
    localparam int B_OCC0       = 9;
    localparam int B_RESET_HELD = 14;

    // Sticky hit bits. They are never cleared by rst_n, so coverage
    // accumulates across resets.
    logic [NBINS-1:0] hit;
    initial hit = '0;

    // Operation classes: push alone, pop alone, both together.
    wire op_push = (push === 1'b1) && (pop === 1'b0);
    wire op_pop  = (push === 1'b0) && (pop === 1'b1);
    wire op_both = (push === 1'b1) && (pop === 1'b1);

    // Occupancy classes from count.
    wire occ_empty = (count === 3'd0);
    wire occ_mid   = (count === 3'd1) || (count === 3'd2) || (count === 3'd3);
    wire occ_full  = (count === 3'd4);

    always @(posedge clk) begin
        if (rst_n === 1'b1) begin
            // Operation x occupancy cross.
            if (op_push && occ_empty) hit[B_PUSH_EMPTY] <= 1'b1;
            if (op_push && occ_mid)   hit[B_PUSH_MID]   <= 1'b1;
            if (op_push && occ_full)  hit[B_PUSH_FULL]  <= 1'b1;
            if (op_pop  && occ_empty) hit[B_POP_EMPTY]  <= 1'b1;
            if (op_pop  && occ_mid)   hit[B_POP_MID]    <= 1'b1;
            if (op_pop  && occ_full)  hit[B_POP_FULL]   <= 1'b1;
            if (op_both && occ_empty) hit[B_BOTH_EMPTY] <= 1'b1;
            if (op_both && occ_mid)   hit[B_BOTH_MID]   <= 1'b1;
            if (op_both && occ_full)  hit[B_BOTH_FULL]  <= 1'b1;

            // Occupancy levels.
            case (count)
                3'd0: hit[B_OCC0 + 0] <= 1'b1;
                3'd1: hit[B_OCC0 + 1] <= 1'b1;
                3'd2: hit[B_OCC0 + 2] <= 1'b1;
                3'd3: hit[B_OCC0 + 3] <= 1'b1;
                3'd4: hit[B_OCC0 + 4] <= 1'b1;
                default: begin
                    if (!$isunknown(count))
                        $error("lifo4_fcov: illegal count value %0d (max 4)", count);
                end
            endcase
        end else if (rst_n === 1'b0) begin
            // Reset applied while the stack holds a word.
            if (!$isunknown(count) && count != 3'd0)
                hit[B_RESET_HELD] <= 1'b1;
        end
    end

    always_comb begin
        planned = NBINS;
        holes   = NBINS - $countones(hit);
    end

endmodule
